sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    // Using 'hardware' as the trigger for critical infrastructure priority escalation.
    // The original requirement references "Critical Infrastructure" but the available
    // request_type choices use 'hardware' as the closest equivalent.
    if (newValue == 'hardware') {
        g_form.setValue('priority', '1');
    }
}
